(function(root){'use strict';function normalize(value){if(typeof value!=='string'||/[\x00-\x20\x7f]/.test(value))throw Error('INVALID_URL');let u;try{u=new URL(value)}catch(_){throw Error('INVALID_URL')}if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw Error('INVALID_URL');if(u.href.length>1024)throw Error('URL_TOO_LONG');return u.href}function make(value){const text=normalize(value),qr=qrcodegen.QrCode.encodeText(text,qrcodegen.QrCode.Ecc.MEDIUM),border=4;let parts=[];for(let y=0;y<qr.size;y++)for(let x=0;x<qr.size;x++)if(qr.getModule(x,y))parts.push('M'+(x+border)+','+(y+border)+'h1v1h-1z');return{text,size:qr.size,border,version:qr.version,path:parts.join(' '),matrix:Array.from({length:qr.size},(_,y)=>Array.from({length:qr.size},(_,x)=>qr.getModule(x,y)))}}function render(container,value){const code=make(value),ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),side=code.size+8,scale=Math.max(4,Math.floor(Math.min(innerHeight*.55,1200)/side));svg.setAttribute('viewBox','0 0 '+side+' '+side);svg.setAttribute('width',side*scale);svg.setAttribute('height',side*scale);svg.setAttribute('role','img');svg.setAttribute('aria-label','QR code for '+new URL(code.text).hostname);svg.setAttribute('shape-rendering','crispEdges');const bg=document.createElementNS(ns,'rect');bg.setAttribute('width',side);bg.setAttribute('height',side);bg.setAttribute('fill','#ffffff');const dark=document.createElementNS(ns,'path');dark.setAttribute('d',code.path);dark.setAttribute('fill','#000000');svg.append(bg,dark);container.replaceChildren(svg);return code}root.OmniQR=Object.freeze({normalize,make,render});})(typeof globalThis!=='undefined'?globalThis:this);
